// Per le altre lingue, evita comunque residui italiani usando l'inglese come fallback finale
// dove non è ancora presente una traduzione specifica.
["es","de","pt","pl","nl","ro","el"].forEach(function(code){
  if(!FAINANCE_1634_FINAL_TRANSLATION_FIX[code]) FAINANCE_1634_FINAL_TRANSLATION_FIX[code]={};
  Object.keys(FAINANCE_1634_FINAL_TRANSLATION_FIX.en).forEach(function(k){
    if(FAINANCE_1634_FINAL_TRANSLATION_FIX[code][k]===undefined) FAINANCE_1634_FINAL_TRANSLATION_FIX[code][k]=FAINANCE_1634_FINAL_TRANSLATION_FIX.en[k];
  });
});
Object.keys(FAINANCE_1634_FINAL_TRANSLATION_FIX).forEach(function(code){
  if(!TRANSLATIONS[code]) TRANSLATIONS[code]={...TRANSLATIONS.en};
  Object.assign(TRANSLATIONS[code], FAINANCE_1634_FINAL_TRANSLATION_FIX[code]);
});


