  // Post-process addizionale: corregge residui misti e rende maiuscola la prima lettera dei menu/etichette brevi.
  var oldPost=typeof fainancePostProcessTranslation==='function'?fainancePostProcessTranslation:null;
  fainancePostProcessTranslation=function(value,lang){
    var code=lang||'it';
    var out=oldPost?oldPost(value,lang):String(value==null?'':value);
    if(!out||code==='it')return out;
    function rep(a,b){out=out.replace(a,b);}
    if(code==='es'){
      var exact={
        'Língua':'Idioma','Lingua seleccionada':'Idioma seleccionado','Fecha formato':'Formato de fecha','Primo giorno settimana':'Primer día de la semana','Valuta principiale':'Moneda principal','153 divisa mostrad...':'153 monedas mostradas...','Dark Modo':'Modo oscuro','Attiva la dark mode':'Activa el modo oscuro','Predeterminido':'Predeterminado','Color botón de conferma':'Color del botón de confirmación','Testo botón uscita':'Texto del botón de gasto','Testo botón entrata':'Texto del botón de ingreso','Stile botón':'Estilo del botón','Pulsante gasto':'Botón de gasto','Fondo del testi widget':'Fondo del texto del widget','Guardar e actualizar widget':'Guardar y actualizar widget','Transazioni recurrentes':'Transacciones recurrentes','Obiettivi de ahorro':'Objetivos de ahorro','presupuesto':'Presupuesto','ajustes':'Ajustes','Ninguna':'Ninguna','Amortised':'Fraccionado','Análisis illimitado':'Análisis ilimitado'
      };
      var trim=out.trim(); if(exact[trim]) out=out.replace(trim,exact[trim]);
      rep(/\bLíngua\b/g,'Idioma'); rep(/\bFecha formato\b/g,'Formato de fecha'); rep(/\bValuta\b/g,'Moneda'); rep(/\bprincipiale\b/g,'principal'); rep(/\bmostrad\.\.\./g,'mostradas...');
      rep(/\bTransazioni recurrentes\b/g,'Transacciones recurrentes'); rep(/\bObiettivi de ahorro\b/g,'Objetivos de ahorro'); rep(/\bDark Modo\b/g,'Modo oscuro');
      rep(/\bbotón de conferma\b/g,'botón de confirmación'); rep(/\bTesto botón\b/g,'Texto del botón'); rep(/\bStile botón\b/g,'Estilo del botón'); rep(/\bPulsante gasto\b/g,'Botón de gasto');
      rep(/\bmanuale\b/g,'manual'); rep(/\bstilo\b/g,'estilo'); rep(/\bseleziona\b/g,'selecciona'); rep(/\binserisci\b/g,'introduce'); rep(/\bvalores\b/g,'valores');
      rep(/\bDisponibile\b/g,'Disponible'); rep(/\bdisponibile\b/g,'disponible'); rep(/\bArchiviato\b/g,'Archivado'); rep(/\barchiviato\b/g,'archivado');
    }
    if(code==='fr'){
      rep(/\bDark Mode\b/g,'Mode sombre'); rep(/\bmanuale\b/g,'manuel'); rep(/\bbottone\b/g,'bouton'); rep(/\bpulsante\b/g,'bouton');
    }
    if(code==='en'){
      rep(/\bmanuale\b/g,'manual'); rep(/\bbottone\b/g,'button'); rep(/\bpulsante\b/g,'button');
    }
    // Maiuscola iniziale per voci menu/etichette brevi non numeriche.
    var stripped=out.trim();
    if(stripped && stripped.length<=55 && !/[.!?]$/.test(stripped) && /^[a-zà-ÿ]/.test(stripped)){
      out=out.replace(stripped, stripped.charAt(0).toUpperCase()+stripped.slice(1));
    }
    return out;
  };


