  var oldPost=typeof fainancePostProcessTranslation==='function'?fainancePostProcessTranslation:null;
  fainancePostProcessTranslation=function(value,lang){
    var code=lang||'it';
    var out=oldPost?oldPost(value,lang):String(value==null?'':value);
    if(!out||code==='it')return out;
    function exact(a,b){if(out.trim()===a)out=out.replace(out.trim(),b);}
    function rep(a,b){out=out.replace(a,b);}
    if(code==='es'){
      exact('Average monthly income (last 12 months):','Ingreso mensual medio (últimos 12 meses):');
      exact('Average monthly income (last 12 months)','Ingreso mensual medio (últimos 12 meses)');
      exact('Copia valori da un altro mes...','Copiar valores de otro mes...');
      exact('Copia valori da un altro mese...','Copiar valores de otro mes...');
      exact('📋 Copia valori da un altro mese...','📋 Copiar valores de otro mes...');
      exact('Carica PDF, immagini, Excel o CSV. I file vengono salvati nei dati dell’account.','Carga PDF, imágenes, Excel o CSV. Los archivos se guardan en los datos de la cuenta.');
      exact('Carica PDF, immagini, Excel o CSV. I file vengono salvati nei dati dell\'account.','Carga PDF, imágenes, Excel o CSV. Los archivos se guardan en los datos de la cuenta.');
      exact('Documenti','Documentos'); exact('📎 Documenti','📎 Documentos');
      exact('Nuova alert','Nueva alerta'); exact('Nuovo alert','Nueva alerta');
      exact('Ilimitada ilimitada','Ilimitada'); exact('Ilimitados ilimitados','Ilimitados');
      rep(/\bIlimitada\s+Ilimitada\b/g,'Ilimitada');
      rep(/\bIlimitados\s+Ilimitados\b/g,'Ilimitados');
      rep(/\billimitati\b/gi,'ilimitados');
      rep(/\billimitate\b/gi,'ilimitadas');
      rep(/\billimitata\b/gi,'ilimitada');
      rep(/\bNuova alert\b/g,'Nueva alerta');
      rep(/\bNuovo alert\b/g,'Nueva alerta');
      rep(/\bCopia valori da un altro mes\.\.\./g,'Copiar valores de otro mes...');
      rep(/\bCopia valori da un altro mese\.\.\./g,'Copiar valores de otro mes...');
      rep(/Average monthly income \(last 12 months\):?/g,'Ingreso mensual medio (últimos 12 meses)');
    }
    if(code==='fr'){
      exact('Average monthly income (last 12 months):','Revenu mensuel moyen (12 derniers mois) :');
      exact('Average monthly income (last 12 months)','Revenu mensuel moyen (12 derniers mois)');
      exact('Copia valori da un altro mese...','Copier les valeurs d’un autre mois...');
    }
    if(code==='en'){
      exact('Copia valori da un altro mese...','Copy values from another month...');
    }
    return out;
  };


