  function ensure(c){ if(!TRANSLATIONS[c]) TRANSLATIONS[c]={}; try{ if(typeof FAINANCE_UI_TRANSLATIONS!=='undefined'&&!FAINANCE_UI_TRANSLATIONS[c]) FAINANCE_UI_TRANSLATIONS[c]={}; }catch(e){} try{ if(typeof FAINANCE_I18N_PHRASES!=='undefined'&&!FAINANCE_I18N_PHRASES[c]) FAINANCE_I18N_PHRASES[c]={}; }catch(e){} }
  function put(c,k,v){ ensure(c); TRANSLATIONS[c][k]=v; try{ if(typeof FAINANCE_UI_TRANSLATIONS!=='undefined') FAINANCE_UI_TRANSLATIONS[c][k]=v; }catch(e){} try{ if(typeof FAINANCE_I18N_PHRASES!=='undefined') FAINANCE_I18N_PHRASES[c][k]=v; }catch(e){} }
